import { Avatar, Tooltip } from 'antd';
import { clsx } from 'clsx';
import React from 'react';
import useStyles from './index.style';

export declare type SizeType = number | 'small' | 'default' | 'large';

export type AvatarItemProps = {
  tips: React.ReactNode;
  src: string;
  size?: SizeType;
  style?: React.CSSProperties;
  onClick?: () => void;
};

export type AvatarListProps = {
  Item?: React.ReactElement<AvatarItemProps>;
  size?: SizeType;
  maxLength?: number;
  excessItemsStyle?: React.CSSProperties;
  style?: React.CSSProperties;
  children:
    | React.ReactElement<AvatarItemProps>
    | React.ReactElement<AvatarItemProps>[];
};

const avatarSizeToClassName = (styles: any, size?: SizeType | 'mini') =>
  clsx(styles.avatarItem, {
    [styles.avatarItemLarge]: size === 'large',
    [styles.avatarItemSmall]: size === 'small',
    [styles.avatarItemMini]: size === 'mini',
  });

const Item: React.FC<AvatarItemProps> = ({ src, size, tips, onClick }) => {
  const { styles } = useStyles();
  const cls = avatarSizeToClassName(styles, size);
  const avatar = tips ? (
    <Tooltip title={tips}>
      <Avatar
        src={src}
        size={size}
        style={{
          cursor: onClick ? 'pointer' : undefined,
        }}
      />
    </Tooltip>
  ) : (
    <Avatar src={src} size={size} />
  );

  return (
    <li className={cls}>
      {onClick ? (
        <button type="button" className={styles.avatarButton} onClick={onClick}>
          {avatar}
        </button>
      ) : (
        avatar
      )}
    </li>
  );
};

const AvatarList: React.FC<AvatarListProps> & {
  Item: typeof Item;
} = ({ children, size, maxLength = 5, excessItemsStyle, ...other }) => {
  const { styles } = useStyles();
  const numOfChildren = React.Children.count(children);
  const numToShow = Math.min(maxLength, numOfChildren);
  const childrenArray = React.Children.toArray(
    children,
  ) as React.ReactElement<AvatarItemProps>[];
  const childrenWithProps = childrenArray.slice(0, numToShow).map((child) =>
    React.cloneElement(child, {
      size,
    }),
  );
  if (numToShow < numOfChildren) {
    const cls = avatarSizeToClassName(styles, size);
    childrenWithProps.push(
      <li key="exceed" className={cls}>
        <Avatar
          size={size}
          style={excessItemsStyle}
        >{`+${numOfChildren - maxLength}`}</Avatar>
      </li>,
    );
  }
  return (
    <div {...other} className={styles.avatarList}>
      <ul> {childrenWithProps} </ul>
    </div>
  );
};

AvatarList.Item = Item;

export default AvatarList;
